import React, { useState, useEffect, useCallback } from "react";
import authService from "../../services/authService";
import { validateMediaFile } from "../utils/mediaValidation";
import { resolveUploadUrl } from "../utils/resolveUploadUrl";
import { useToast } from "./ToastProvider";
import UploadProgressBar from "./UploadProgressBar";
import MediaPreviewButton from "./MediaPreviewButton";

const MEDIA_FIELD_TYPES = ["image", "video", "media"];

const CrudForm = ({ fields, initialValues, onSubmit, onCancel }) => {
  const [values, setValues] = useState({});
  const [dynamicOptions, setDynamicOptions] = useState({});
  const [uploading, setUploading] = useState({});
  const [uploadProgress, setUploadProgress] = useState({});
  const [mediaKind, setMediaKind] = useState({});
  const [showUrlInput, setShowUrlInput] = useState({});
  const toast = useToast();

  useEffect(() => {
    const defaults = {};
    fields.forEach((field) => {
      const fallback = field.type === "checkbox" ? (field.defaultValue ?? false) : (field.defaultValue ?? "");
      defaults[field.name] = initialValues?.[field.name] ?? fallback;
    });
    setValues(defaults);
  }, [initialValues, fields]);

  useEffect(() => {
    fields.forEach((field) => {
      if (field.type === "select" && typeof field.optionsLoader === "function") {
        field.optionsLoader().then((options) => {
          setDynamicOptions((prev) => ({ ...prev, [field.name]: options }));
        }).catch(() => {
          setDynamicOptions((prev) => ({ ...prev, [field.name]: [] }));
        });
      }
    });
  }, [fields]);

  const handleChange = (e) => {
    const { name, type, value, checked } = e.target;
    setValues((prev) => ({ ...prev, [name]: type === "checkbox" ? checked : value }));
  };

  const handleMediaUpload = useCallback(async (fieldName, kind, e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const validateOpts = kind === "video" ? { videoOnly: true } : kind === "media" ? {} : { allowVideo: false };
    const { valid, error } = validateMediaFile(file, validateOpts);
    if (!valid) { toast.error(error); e.target.value = ""; return; }

    setMediaKind((prev) => ({ ...prev, [fieldName]: file.type.startsWith("video") ? "video" : "image" }));

    const previewUrl = URL.createObjectURL(file);
    setValues((prev) => ({ ...prev, [fieldName]: previewUrl }));

    setUploading((prev) => ({ ...prev, [fieldName]: true }));
    setUploadProgress((prev) => ({ ...prev, [fieldName]: 0 }));
    try {
      const fd = new FormData();
      fd.append("path", "ADMIN_UPLOAD");
      fd.append("file", file);
      const res = await authService.uploadFile(fd, (pct) => setUploadProgress((prev) => ({ ...prev, [fieldName]: pct })));
      const raw = res.data?.url || res.data?.data?.url || res.data?.virtualPath || res.data?.fileUrl || "";
      const url = resolveUploadUrl(raw);
      if (url) {
        setValues((prev) => ({ ...prev, [fieldName]: url }));
      } else {
        toast.error("Upload succeeded but no file URL was returned.");
        setValues((prev) => ({ ...prev, [fieldName]: "" }));
      }
    } catch (err) {
      toast.error(err.response?.data?.message || "Upload failed.");
      setValues((prev) => ({ ...prev, [fieldName]: "" }));
    } finally {
      URL.revokeObjectURL(previewUrl);
      setUploading((prev) => ({ ...prev, [fieldName]: false }));
      setUploadProgress((prev) => ({ ...prev, [fieldName]: 0 }));
    }
  }, [toast]);

  const handleSubmit = (e) => {
    e.preventDefault();
    const missingMedia = fields.find(
      (field) => field.required && MEDIA_FIELD_TYPES.includes(field.type) && !values[field.name]
    );
    if (missingMedia) { toast.error(`${missingMedia.label} is required.`); return; }

    const normalized = { ...values };
    fields.forEach((field) => {
      if (field.type === "checkbox") {
        normalized[field.name] = normalized[field.name] ? 1 : 0;
      }
      if (field.type === "number") {
        normalized[field.name] = normalized[field.name] === "" ? "" : parseFloat(normalized[field.name]);
      }
    });
    onSubmit(normalized);
  };

  const isUploading = Object.values(uploading).some(Boolean);

  const renderMediaField = (field, kind) => {
    const accept =
      kind === "image" ? "image/jpeg,image/png,image/webp,image/gif"
      : kind === "video" ? "video/mp4,video/webm,video/quicktime"
      : "image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm,video/quicktime";
    const hint =
      kind === "image" ? "JPG, PNG, WEBP, or GIF."
      : kind === "video" ? "MP4, WEBM, or MOV."
      : "JPG, PNG, WEBP, GIF images or MP4, WEBM, MOV videos.";
    const previewKind = kind === "media" ? mediaKind[field.name] : kind;

    return (
      <div>
        <div className="d-flex align-items-center gap-2 flex-wrap">
          <input
            type="file"
            accept={accept}
            className="form-control"
            style={{ maxWidth: 280 }}
            onChange={(e) => handleMediaUpload(field.name, kind, e)}
            disabled={uploading[field.name]}
          />
          <MediaPreviewButton url={values[field.name]} kind={previewKind} />
          <button
            type="button"
            className="btn btn-sm btn-link px-0"
            onClick={() => setShowUrlInput((p) => ({ ...p, [field.name]: !p[field.name] }))}
          >
            {showUrlInput[field.name] ? "Hide manual URL" : "Enter URL manually"}
          </button>
        </div>
        <div className="form-text">{hint}</div>
        {uploading[field.name] && <UploadProgressBar percent={uploadProgress[field.name] || 0} />}
        {showUrlInput[field.name] && (
          <input
            className="form-control mt-2"
            type="text"
            name={field.name}
            value={values[field.name] ?? ""}
            onChange={handleChange}
            placeholder="Paste an external URL (e.g. a YouTube link)"
          />
        )}
      </div>
    );
  };

  return (
    <form onSubmit={handleSubmit}>
      {fields.map((field) => {
        const options = field.type === "select" ? (field.options || dynamicOptions[field.name] || []) : [];
        return (
          <div className="mb-3" key={field.name}>
            <label className="form-label">{field.label}</label>
            {field.type === "select" ? (
              <select
                className="form-select"
                name={field.name}
                value={values[field.name] || ""}
                onChange={handleChange}
                required={field.required}
              >
                <option value="">Select {field.label}</option>
                {options.map((opt) => (
                  <option key={opt.value} value={opt.value}>
                    {opt.label}
                  </option>
                ))}
              </select>
            ) : field.type === "textarea" ? (
              <textarea
                className="form-control"
                name={field.name}
                value={values[field.name] || ""}
                onChange={handleChange}
                required={field.required}
                rows={field.rows || 3}
              />
            ) : field.type === "checkbox" ? (
              <div className="form-check mt-1">
                <input
                  className="form-check-input"
                  type="checkbox"
                  name={field.name}
                  id={`field_${field.name}`}
                  checked={!!values[field.name]}
                  onChange={handleChange}
                />
                <label className="form-check-label" htmlFor={`field_${field.name}`}>
                  {field.label}
                </label>
              </div>
            ) : field.type === "image" ? (
              renderMediaField(field, "image")
            ) : field.type === "video" ? (
              renderMediaField(field, "video")
            ) : field.type === "media" ? (
              renderMediaField(field, "media")
            ) : (
              <input
                className="form-control"
                type={field.type || "text"}
                name={field.name}
                value={values[field.name] ?? ""}
                onChange={handleChange}
                required={field.required}
              />
            )}
          </div>
        );
      })}
      <div className="d-flex gap-2">
        <button type="submit" className="btn btn-success" disabled={isUploading}>
          {isUploading ? "Uploading..." : "Save"}
        </button>
        <button type="button" className="btn btn-secondary" onClick={onCancel}>
          Cancel
        </button>
      </div>
    </form>
  );
};

export default CrudForm;
